import{_ as t,H as a,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"03 | 技术型创业公司如何把握发展与管理的节奏感？","description":"","frontmatter":{},"headers":[{"level":2,"title":"技术积累阶段","slug":"技术积累阶段","link":"#技术积累阶段","children":[]},{"level":2,"title":"产品打磨阶段","slug":"产品打磨阶段","link":"#产品打磨阶段","children":[]},{"level":2,"title":"商业化阶段","slug":"商业化阶段","link":"#商业化阶段","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"技术领导力实战笔记2022/03｜技术型创业公司如何把握发展与管理的节奏感？.md","filePath":"技术领导力实战笔记2022/03｜技术型创业公司如何把握发展与管理的节奏感？.md","lastUpdated":1795558086000}'),s={name:"技术领导力实战笔记2022/03｜技术型创业公司如何把握发展与管理的节奏感？.md"};function o(E,e,r,l,p,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_03-技术型创业公司如何把握发展与管理的节奏感" tabindex="-1">03 | 技术型创业公司如何把握发展与管理的节奏感？ <a class="header-anchor" href="#_03-技术型创业公司如何把握发展与管理的节奏感" aria-label="Permalink to &quot;03 | 技术型创业公司如何把握发展与管理的节奏感？&quot;">​</a></h1><p>你好，我是王璞，前数人云创始人，现在是 DatenLord 联合创始人，更早之前在 Google 任职。</p><p>最近几年，技术领域特别是基础设施相关的技术领域创业很热，不少技术类创业公司如雨后春笋般冒出来。但是很多技术创业公司在成长的过程中，都碰到了各种技术团队管理方面的问题，且每个阶段的主要矛盾各有不同。</p><p>因此，在公司发展的不同阶段，需要搭建不一样的技术团队，采用不同的技术管理方式，解决不同阶段的问题。也就是说，公司发展需要节奏感，不同阶段要有不同的侧重点。一旦节奏感乱了，就会特别拧巴，导致公司的管理顾此失彼，流失大量技术人才。</p><p>针对上述技术型创业公司不同发展阶段，以及技术团队管理方式，我来分享一些我个人的观点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/03/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/03/1.png" alt=""></a></p><h2 id="技术积累阶段" tabindex="-1">技术积累阶段 <a class="header-anchor" href="#技术积累阶段" aria-label="Permalink to &quot;技术积累阶段&quot;">​</a></h2><p>技术型创业公司的早期技术积累阶段，好比是盖高楼打地基阶段，地基挖多深也就决定了楼房能盖多高。在这个阶段，技术型创业公司需要沉下心，深入挖掘和钻研底层技术，建立相当的技术壁垒。而这个阶段恰恰是最容易被技术型创业公司忽视的。</p><p>试想，如果一个技术型创业团队很快就能搞出产品，并且还能快速商业化落地，那么科技巨头大厂也能很快复制出类似的产品，大厂的资源是创业公司不能比拟的，所以技术型创业团队需要构建自己的技术壁垒，防止巨头超车。所谓技术壁垒就是要有相当的技术难度，而且无论是对大厂还是创业公司，这个难度都很有挑战性，才算是真正的技术壁垒。</p><p>这次中美贸易战，已经让所有人体会到被核心技术卡脖子的痛苦。在中美贸易战之前，国内商业化环境长期忽视技术的重要性，觉得技术不重要，更看重销售变现能力。而且国内太多的技术团队过于浮躁，不愿意啃硬骨头，太多拿来主义，特别是基础设施相关的技术团队，大部分只是使用底层开源技术，却不深入钻研，没有底层开源技术的维护和二次开发能力。长此以往，技术团队缺乏核心技术积累，自然无法吸引到优秀的技术人才。</p><p>第一个阶段的技术型创业公司其实很像研究机构，深挖相关核心技术的同时，开展各种对外合作交流，比如跟开源社区合作，跟高校科研院所合作等等。因为对处于第一阶段的技术型创业公司而言，必须要搞最前沿的技术，老的技术要么已经成熟没有技术壁垒，要么被大公司垄断，只有前沿技术才有可能给技术型创业公司带来一线生机。</p><p>而最前沿的技术往往来自研究机构，或者各种早期开源项目，需要技术创业团队在早期有良好的技术嗅觉和技术敏感度。在钻研核心技术的同时，发掘潜在的技术方向，同时扩大自身在特定技术领域的影响力和知名度，并通过最前沿的技术来吸引优秀的人才。优秀的人才往往也具有很好的技术敏锐度和很强的学习能力，能够在第一时间关注到前沿技术。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/03/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/03/2.png" alt=""></a></p><p>处于第一阶段的技术型创业公司，对技术团队的管理相对简单和宽松，更注重单兵效率，给优秀的技术人员创造宽松的氛围和环境，最大化地激发他们的创造力，而且在研发进度的管理上要避免细粒度管理，更多采用研究型项目的管理方式。设定大目标之后，给予充分的信任和自由，减少微观管理。</p><p>但是在加强技术交流和分享，营造技术氛围，弱化微观管理的同时，要靠各种技术分享和交流来促进技术输出，一方面了解最前沿技术的发展情况，另一方面建立团队的技术品牌和影响力，吸引更多优秀的人加入，从而形成正向循环，不断加快技术积累，进而推动团队的研发进展。</p><h2 id="产品打磨阶段" tabindex="-1">产品打磨阶段 <a class="header-anchor" href="#产品打磨阶段" aria-label="Permalink to &quot;产品打磨阶段&quot;">​</a></h2><p>第二阶段的技术型创业公司，已经有了一定的技术积累，开始做产品，并开始尝试产品推广。这个阶段对于基础设施相关的技术创业公司来说，常采用开源策略来实现产品的快速推广。对于技术型创业公司，在这个阶段特别是采用开源策略之后，非常忌讳过早地开始商业化。因为这个阶段虽然有一定的技术积累，但是产品本身尚不成熟，需要很多早期用户来试用，提出反馈和改进意见。</p><p>如果过早开始商业化，反而会导致客户各种不满意，特别是开源产品，一旦过早采取收费策略，会因为产品不成熟产生各种负面反馈，并在开源社区中传播，导致口碑崩塌。</p><p>有一个非常典型的失败案例，就是美国的 Docker 公司，曾经由于过早地开始收费，把原本很受欢迎的开源项目 Docker 变成商业化产品，还把原来的名字从 Docker 改为了 Mobby。这个举动不仅没有吸引到更多付费商业客户，还得罪了一众社区用户和开发者，导致 Docker 公司发展势头一落千丈。最近 Docker 才又重新把重心放在开源社区和开发者层面，这才逐渐有了起色，但是也远不能跟当初迅猛的发展势头相媲美。</p><p>第二个阶段的技术团队管理，要从第一阶段的注重单兵效率转变为注重团队效率，从研究型技术团队管理方式转向产品型技术团队管理方式。同时第二阶段技术团队的规模往往会快速扩张，而且主要招聘的是偏工程的技术人员，这对技术团队管理能力考验很大，很多技术团队也容易在这个阶段出问题，特别是如果管理方式的变迁过程不够平滑，会让早期核心技术人员感觉到技术氛围下降，流失核心技术人员。所以第二阶段技术团队管理的挑战在于如何提升管理能力，打造高效率的技术研发团队。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/03/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/03/3.png" alt=""></a></p><p>提升技术团队管理能力，一方面要从早期核心技术团队里培养出一批 Tech Lead，每个 TechLead 带着十人左右规模的小团队进行产品化研发。这些早期核心团队成员参与了从 0 到 1 的技术积累过程，对产品有感情、有憧憬，让他们负责产品落地最合适不过。每个小团队十人左右这个规模源自 Amazon 的两个 Pizza 原则，即负责每个微服务的团队人数不超过两个 Pizza能吃饱的规模，小团队有利于降低团队内部沟通成本，同时整体研发团队的管理也要扁平化。</p><p>另一方面，更重要的是建立技术团队管理的体系，并落实到工具层面。技术团队非常忌讳人盯人管理，而且人盯人的管理方式效率很低。</p><p>重视技术管理体系建设，并落实到工具层面，包括自动化代码检查机制、代码 Review 机制、持续集成流程（测试和验证相关）、发布流程、监控告警等运维流程、文档流程等等，而且这些机制和流程不能只停留在口头或文字层面，要有切实的工具来保证这些机制和流程顺利地执行下去。比如代码的检查机制，必须要有自动化检查工具，能够检查代码的风格，甚至自动修复代码不满足风格约束的地方。</p><p>这方面 Google 做得非常好，它的内部有各种平台和工具，帮助技术团队快速搭建各种流程，比如代码管理流程、测试流程、发布流程、运维流程等等，而且这些流程都是基于平台和工具自动化或半自动完成的，提高效率的同时还落实了各种管理的规章制度，比如代码风格规约、测试覆盖率要求等等。</p><p>再比如持续集成流程，这个环节经常会因为早期研发阶段没有及时搭建持续集成工具平台，造成第二阶段建设持续集成平台工作量大的问题。但是即便有难度，也要重视自动化持续集成流程平台建设，让工具自动化运行各种测试，在开发和测试阶段就尽可能早发现问题，并及时修复问题，而不是等产品发布后出现问题再修复。因为这样不仅修复成本高，而且在客户使用场景出现问题，很影响产品的口碑。</p><p>此外，第二阶段的技术型创业公司还要保留第一阶段的研究型技术团队，为长期的技术发展做积累，并积极探索新的技术产品方向。研究型技术团队不需要很大的规模，但是要能持续吸引最优秀的研究型人才加入，持续塑造公司的技术口碑和影响力。</p><h2 id="商业化阶段" tabindex="-1">商业化阶段 <a class="header-anchor" href="#商业化阶段" aria-label="Permalink to &quot;商业化阶段&quot;">​</a></h2><p>在产品逐步成熟之后，就可以开始尝试商业化落地了。除技术团队外，也会搭建销售市场团队，或交付团队。这个阶段技术团队内部的管理方式与第二阶段并无本质差异，但是要注意技术团队与非技术团队之间的沟通协作，这个方面非常重要，弄不好就会导致部门墙，但这节课我们主要探讨的是技术团队的管理，这里就不展开技术团队和非技术团队协作的问题了。</p><p>特别强调一点，进入第三个阶段，技术型创业公司的管理团队里，至少要有一位联合创始人或合伙人级别的技术管理者坚持在技术一线，不仅做技术管理，还要亲自参与技术研发，甚至需要经常接触代码。</p><p>像 Google 的资深 fellow，Jeff Dean 博士，早就功成名就，但仍然坚持在一线做技术研发，每隔几年就推出革命性的技术产品，从 MapReduce 到 Google Brain，为 Google 塑造了极强的技术口碑和影响力。</p><p>因为技术的演变日新月异，一旦技术型创业公司的管理层长时间不接触一线研发，就会失去技术的敏锐度，非常危险。长期脱离一线技术研发，管理者对技术的理解停留在过去的认知上，但又要对各种技术类产品做决策，这会导致管理层根据过去对技术的认知，做出保守的判断，久而久之会导致技术产品落伍，失去技术竞争力，这就动摇了技术型创业公司最核心的根基。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>总之，技术型创业公司的核心竞争力来源于其技术积累，并通过技术产品化，进而实现技术的商业价值变现。这整个过程中会经历不同的发展阶段，对技术团队的人员和管理要求不尽相同，如果你正在创业型技术公司做管理工作，不妨对照着这三个阶段来确定目前工作的重心。当然每个公司的情况不尽相同，你可以根据自己公司的实际情况灵活应对。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>学完这节课的内容，你能不能试着简述一下，处在产品打磨阶段的技术团队应该采用什么样的管理策略？这节课的分享源于我个人过去几年创业的一些经验和体会，难免有局限，如果你有自己的想法和见解，欢迎在评论区分享，我们一起交流，也欢迎你把这节课分享给需要的朋友。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/03/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/03/4.png" alt=""></a></p>',37)])])}const g=t(s,[["render",o]]);export{c as __pageData,g as default};
